param([int]$TimeoutSeconds = 180, [int]$AsyncBehaviorTimeoutSeconds = 180, [switch]$Capture, [switch]$CaptureShield, [switch]$CaptureElite, [switch]$KeyposesOnly, [switch]$CapturePairReload, [switch]$CaptureReview, [switch]$CaptureChargeEvasion, [switch]$CaptureMotion, [switch]$CaptureCloseCombat)
$ErrorActionPreference = 'Stop'
if ($KeyposesOnly -and -not $CaptureElite) { throw 'KeyposesOnly requires CaptureElite.' }
if (($Capture -or $CaptureShield -or $CaptureElite -or $CapturePairReload -or $CaptureChargeEvasion) -and -not $PSBoundParameters.ContainsKey('TimeoutSeconds')) { $TimeoutSeconds = 600 }
if (($Capture -or $CaptureShield -or $CaptureElite -or $CapturePairReload -or $CaptureChargeEvasion) -and -not $PSBoundParameters.ContainsKey('AsyncBehaviorTimeoutSeconds')) {
    # Full motion writes 180 lossless captures through CS6 trace; keyposes need much less time.
    $AsyncBehaviorTimeoutSeconds = if ($CaptureElite -and -not $KeyposesOnly) { 1200 } else { 600 }
}
# Build the same RSL linkage scope used by the game; separate loadMovie libraries cannot share weapons.
& python -X utf8 -B (Join-Path $PSScriptRoot '../tools/cf6-soldier-assets/build-test-consumer.py')
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$template = if ($CaptureCloseCombat) { 'scripts/test-runners/cf6-soldier/TestLoader-close-combat.as.template' } elseif ($CaptureMotion) { 'scripts/test-runners/cf6-soldier/TestLoader-motion.as.template' } elseif ($CaptureChargeEvasion) { 'scripts/test-runners/cf6-soldier/TestLoader-charge-evasion.as.template' } elseif ($CaptureReview) { 'scripts/test-runners/cf6-soldier/TestLoader-review.as.template' } elseif ($CapturePairReload) { 'scripts/test-runners/cf6-soldier/TestLoader-pair-reload.as.template' } elseif ($CaptureElite -and $KeyposesOnly) { 'scripts/test-runners/cf6-soldier/TestLoader-elite-keyposes.as.template' } elseif ($CaptureElite) { 'scripts/test-runners/cf6-soldier/TestLoader-elite-capture.as.template' } elseif ($CaptureShield) { 'scripts/test-runners/cf6-soldier/TestLoader-shield-capture.as.template' } elseif ($Capture) { 'scripts/test-runners/cf6-soldier/TestLoader-capture.as.template' } else { 'scripts/test-runners/cf6-soldier/TestLoader.as.template' }
& (Join-Path $PSScriptRoot 'test-runners/run-focused-testloader.ps1') -DomainId cf6-soldier -CompileTargetRelativePath scripts/Cf6SoldierNativeHost/Cf6SoldierNativeHost.xfl -CompileSwfRelativePath scripts/Cf6SoldierNativeHost.swf -TemplateRelativePath $template -SuiteRelativePaths 'scripts/类定义/org/flashNight/arki/unit/Action/Melee/Cf6SoldierAssetTest.as' -SuiteFqns 'org.flashNight.arki.unit.Action.Melee.Cf6SoldierAssetTest' -ExpectedTracePatterns @('Cf6SoldierAssetTest: \d+ passed, 0 failed; 200 actual timeline cases') -SuccessSummary '普通与精英特种兵原生动作、统一射击、破盾和死亡边界通过' -TimeoutSeconds $TimeoutSeconds -AsyncBehaviorTimeoutSeconds $AsyncBehaviorTimeoutSeconds
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
